function returnHome(b){if(!b.trail.length)return;let g=state.game.grid,best=null,dist=Infinity;for(let y=Math.max(0,b.y-10);y<Math.min(N,b.y+11);y++)for(let x=Math.max(0,b.x-10);x<Math.min(N,b.x+11);x++)if(g[y][x]===b.id){let d=Math.abs(x-b.x)+Math.abs(y-b.y);if(d<dist){dist=d;best={x,y}}}if(best){let opts=[{x:Math.sign(best.x-b.x),y:0},{x:0,y:Math.sign(best.y-b.y)}].filter(d=>d.x||d.y).sort(()=>Math.random()-.5);for(let d of opts)if(isInside(b.x+d.x,b.y+d.y)){moveEntity(b,d,g);return}}else b.trail=[]}
function botDirection(b){let g=state.game.grid,p=state.game.player;
 if(b.trail.length){let threat=p.alive&&Math.abs(p.x-b.x)+Math.abs(p.y-b.y)<9;if(!b.plan)b.plan={returning:false,left:5+Math.floor(Math.random()*7)};if(threat||b.trail.length>=b.plan.left)b.plan.returning=true;if(b.plan.returning){let nearest=null,dist=1e9;for(let y=Math.max(0,b.y-12);y<Math.min(N,b.y+13);y++)for(let x=Math.max(0,b.x-12);x<Math.min(N,b.x+13);x++)if(g[y][x]===b.id){let d=Math.abs(x-b.x)+Math.abs(y-b.y);if(d<dist){dist=d;nearest={x,y}}}if(nearest){let choices=[{x:Math.sign(nearest.x-b.x),y:0},{x:0,y:Math.sign(nearest.y-b.y)}].filter(d=>d.x||d.y);return choices.sort(()=>Math.random()-.5)[0]||{x:0,y:0}}}
 let d=b.dir;if(!isInside(b.x+d.x,b.y+d.y)||(!d.x&&!d.y)||g[b.y+d.y]?.[b.x+d.x]===b.id){b.plan.returning=true;return botDirection(b)}return d}
 if(!b.plan&&Math.random()<(.13+(state.difficulty==='Expert'?.14:0))){let directions=[{x:1,y:0},{x:-1,y:0},{x:0,y:1},{x:0,y:-1}].filter(d=>isInside(b.x+d.x,b.y+d.y)&&g[b.y+d.y][b.x+d.x]!==b.id);if(directions.length){let d=directions[Math.floor(Math.random()*directions.length)];b.dir=d;b.plan={returning:false,left:4+Math.floor(Math.random()*(state.difficulty==='Easy'?4:9))};return d}}
 let opts=[b.dir,{x:1,y:0},{x:-1,y:0},{x:0,y:1},{x:0,y:-1}].filter((d,i,a)=>d.x||d.y).filter(d=>isInside(b.x+d.x,b.y+d.y)&&g[b.y+d.y][b.x+d.x]===b.id&&!(d.x===-b.dir.x&&d.y===-b.dir.y));if(!opts.length)opts=[{x:1,y:0},{x:-1,y:0},{x:0,y:1},{x:0,y:-1}].filter(d=>isInside(b.x+d.x,b.y+d.y)&&g[b.y+d.y][b.x+d.x]===b.id);return opts[Math.floor(Math.random()*opts.length)]||{x:0,y:0}
}
function playerDirection(){let j=joyVector;let x=0,y=0;if(j.x||j.y){if(Math.abs(j.x)>Math.abs(j.y))x=Math.sign(j.x);else y=Math.sign(j.y)}else{if(state.keys.ArrowLeft||state.keys.a)x=-1;if(state.keys.ArrowRight||state.keys.d)x=1;if(state.keys.ArrowUp||state.keys.w)y=-1;if(state.keys.ArrowDown||state.keys.s)y=1;if(x&&y){if(Math.abs(x)>Math.abs(y))y=0;else x=0}}return{x,y}}
function loop(now){let g=state.game;if(!g||!$('#game').classList.contains('active'))return;if(!g.paused&&!g.over){let dt=Math.min(.06,(now-lastFrame)/1000);g.elapsed+=dt;if(g.time>0){g.time-=dt;if(g.time<=0){g.time=0;endGame(true)}}if(now-g.lastMove>STEP){let d=playerDirection();if(d.x||d.y)moveEntity(g.player,d,g.grid);g.lastMove=now}if(now-g.lastAI>STEP*(state.difficulty==='Expert'?.72:state.difficulty==='Hard'?.88:state.difficulty==='Easy'?1.5:1.12)){for(let b of g.bots)if(b.alive){let d=botDirection(b);if(d.x||d.y)moveEntity(b,d,g.grid)}g.lastAI=now}}
 lastFrame=now;draw();raf=requestAnimationFrame(loop)}
function territory(id){let n=0;for(let y=0;y<N;y++)for(let x=0;x<N;x++)if(state.game.grid[y][x]===id)n++;return n/(N*N)*100}
function draw(){let g=state.game,w=innerWidth,h=innerHeight;if(!g){drawPromo();return}ctx.clearRect(0,0,w,h);ctx.fillStyle='#111b24';ctx.fillRect(0,0,w,h);let cell=24,camX=g.player.x*cell,camY=g.player.y*cell,left=w/2-camX,top=h/2-camY;
 let x0=Math.max(0,Math.floor(-left/cell)-1),y0=Math.max(0,Math.floor(-top/cell)-1),x1=Math.min(N,Math.ceil((w-left)/cell)+1),y1=Math.min(N,Math.ceil((h-top)/cell)+1);
 ctx.fillStyle='#172630';ctx.fillRect(left,top,N*cell,N*cell);
 for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let id=g.grid[y][x];if(id){let col=id===1?skinColor():g.bots.find(b=>b.id===id)?.color||'#546477';ctx.globalAlpha=id===1?.93:.83;ctx.fillStyle=col;ctx.fillRect(left+x*cell+1,top+y*cell+1,cell-2,cell-2);ctx.globalAlpha=1}else{ctx.fillStyle=(x+y)%2?'#192a35':'#1c2d38';ctx.fillRect(left+x*cell,top+y*cell,cell,cell)}}
 // Fine grid and arena boundary.
 ctx.strokeStyle='#ffffff0b';ctx.lineWidth=1;ctx.beginPath();for(let x=x0;x<=x1;x++){ctx.moveTo(left+x*cell,top+y0*cell);ctx.lineTo(left+x*cell,top+y1*cell)}for(let y=y0;y<=y1;y++){ctx.moveTo(left+x0*cell,top+y*cell);ctx.lineTo(left+x1*cell,top+y*cell)}ctx.stroke();ctx.strokeStyle='#d5efff88';ctx.lineWidth=3;ctx.strokeRect(left,top,N*cell,N*cell);
 for(let e of [...g.bots,g.player]){if(!e.alive)continue;let col=e.id===1?skinColor():e.color;if(e.trail.length){ctx.beginPath();ctx.setLineDash([6,4]);ctx.lineWidth=cell*.72;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=col;ctx.globalAlpha=.78;for(let [i,p] of e.trail.entries()){let px=left+(p.x+.5)*cell,py=top+(p.y+.5)*cell;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py)}ctx.lineTo(left+(e.x+.5)*cell,top+(e.y+.5)*cell);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1}
 let cx=left+(e.x+.5)*cell,cy=top+(e.y+.5)*cell;ctx.fillStyle='#07121acc';ctx.beginPath();ctx.arc(cx,cy,cell*.52,0,Math.PI*2);ctx.fill();ctx.fillStyle=col;ctx.beginPath();ctx.roundRect(cx-cell*.38,cy-cell*.38,cell*.76,cell*.76,5);ctx.fill();if(e.id===1){ctx.strokeStyle='#ffffff';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#14222a';ctx.font='bold 11px Outfit';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',cx,cy)}}
 updateHUD();drawMini();}
function updateHUD(){let g=state.game,percent=territory(1),remaining=Math.max(0,Math.floor(g.time)),mins=Math.floor(remaining/60),secs=remaining%60;$('#territoryPct').textContent=percent.toFixed(1)+'%';$('#timerText').textContent=g.mode==='Survival'?`${Math.floor(g.elapsed/60)}:${String(Math.floor(g.elapsed%60)).padStart(2,'0')}`:`${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;
 let ranked=[{name:'You',id:1,p:percent,color:skinColor()},...g.bots.filter(b=>b.alive).map(b=>({name:b.name,id:b.id,p:territory(b.id),color:b.color}))].sort((a,b)=>b.p-a.p).slice(0,5);$('#rankRows').innerHTML=ranked.map(r=>`<div class="rank-row"><i class="rank-dot" style="background:${r.color}"></i>${r.name}<span>${r.p.toFixed(0)}%</span></div>`).join('')}
function drawMini(){let g=state.game;if(!g)return;let s=124/N;mctx.fillStyle='#172630';mctx.fillRect(0,0,124,124);for(let y=0;y<N;y++)for(let x=0;x<N;x++){let id=g.grid[y][x];if(id){mctx.globalAlpha=.9;mctx.fillStyle=id===1?skinColor():g.bots.find(b=>b.id===id)?.color||'#566';mctx.fillRect(x*s,y*s,s+.2,s+.2)}}mctx.globalAlpha=1;mctx.strokeStyle='#fff';mctx.lineWidth=1.5;mctx.strokeRect(g.player.x*s-1,g.player.y*s-1,s+2,s+2)}

